manifest={'schema':1,'sdk':1,'id':'edgajuman.wasm-lab','name':'WASM Lab · Warm Grade','author':'Edgajuman','version':'1.0.0','min_app':'2.3.0','description':'Ejemplo real del SDK: contador persistente y efecto de temperatura RGBA. Parámetro JSON del efecto: {"warmth":0.08}.','license':'MIT','component':'component.wasm','permissions':{'render':True},'files':[{'path':'component.wasm','size':len(data),'sha256':hashlib.sha256(data).hexdigest()}],'widgets':[{'id':'counter','title':'Contador WASM','controls':[{'id':'count','kind':'label','label':'Contador persistente','value':'0'},{'id':'increment','kind':'button','label':'+1','action':'increment'}]}],'actions':[],'changelog':'1.0.0: widget persistente y efecto de color, sin red ni imports del host.'}
(p/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
